# -*- coding: utf-8 -*-
"""Pagine USA di settore e guide (en-US). Usa gli elenchi e i blocchi di pagine-dati-usa.py.
   Si genera con:  python3 seo-tools/pagine-build-usa.py"""
import os, importlib.util
_s = importlib.util.spec_from_file_location('usa1', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'pagine-dati-usa.py'))
U = importlib.util.module_from_spec(_s); _s.loader.exec_module(U)
OGGI = U.OGGI
PAGINE = []
AREA = [U.US]

def citta_sec(frase):
    return {"id":"cities","tipo":"testo","eyebrow":"Across the US",
            "h2":"Wherever <span class=\"grad\">you are</span>",
            "corpo":[frase, U.lista_citta_html()]}

def comuni(*idx):
    f = U.faq_comuni("your city", "ET")
    return [f[i] for i in idx]

def altri_per(url, extra=()):
    lst = [x for x in U.INDUSTRIE + U.EXTRA if x[1] != url and x[1] not in [e[1] for e in extra]][:7] + [x for x in U.GUIDE if x[1] != url][:2]
    return list(extra) + lst + [("All US cities we work with","/en/united-states/"),("Pricing","/en/pricing/")]

def settore(url, title, desc, eyebrow, h1, lead, cards_h2, cards, s1, s2, faq, svc_name, svc_type, catalogo, extra=(), chi=None):
    return {
     "lang":"en","url":url,"title":title,"desc":desc,
     "ogtitle":title.replace(" | Danova Tech","") + " — Danova Tech","ogdesc":desc,
     "crumbs":[("United States","/en/united-states/"),(eyebrow,None)],
     "eyebrow":eyebrow,"h1":h1,"lead":lead,
     "cta1":"Book a free call","cta2":"What we build",
     "sezioni":[
       {"id":"build","tipo":"cards","eyebrow":"What we build","h2":cards_h2,"corpo":cards},
       {"id":"reality","tipo":"testo","eyebrow":s1[0],"h2":s1[1],"corpo":s1[2]},
       {"id":"details","tipo":"testo","eyebrow":s2[0],"h2":s2[1],"corpo":s2[2]},
       U.metodo(),
       citta_sec("We work remotely with %s across the country, with calls in your morning and the build happening while you are offline. Local market notes, city by city:" % (chi or eyebrow.lower()))],
     "faqtitle":"The questions we <span class=\"grad\">always get.</span>",
     "faq":faq + comuni(0, 4, 2),
     "ctabox":U.ctabox("the US"),
     "altrititle":"Related pages",
     "altri":altri_per(url, extra),
     "svc":{"name":svc_name,"type":svc_type,"desc":desc,"area":AREA,
            "lingue":["English","Spanish","Italian"],"catalogo":catalogo},
    }

